import * as XLSX from "xlsx";
import type { Alert } from "@/lib/api/alerts";
import type { FlightHistory } from "@/lib/api/flightHistory";

const formatDate = (date: string) => {
  return new Date(date).toLocaleString("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  });
};

/* =====================================================
        ALERT EXCEL
===================================================== */

export const downloadAlertExcel = (
  alerts: Alert[],
  fileName = "Alert_Report"
) => {
const rows = alerts.map((alert, index) => ({
  "Sr No": index + 1,
  "Alert ID": alert.id,
  Type: alert.type,
  Sensor: alert.sensor?.name ?? "-",
  "Sensor ID": alert.sensorId,
  Area: alert.sensor?.area?.name ?? "-",

  Latitude: alert.sensor?.latitude ?? "-",
  Longitude: alert.sensor?.longitude ?? "-",

  Message: alert.message,
  Status: alert.status,
  Created: formatDate(alert.createdAt),
}));

  const worksheet = XLSX.utils.json_to_sheet(rows);

  worksheet["!cols"] = [
    { wch: 8 },
    { wch: 35 },
    { wch: 15 },
    { wch: 20 },
    { wch: 18 },
    { wch: 20 },
      { wch: 16 }, // Latitude
  { wch: 16 }, // Longitude
    { wch: 45 },
    { wch: 15 },
    { wch: 22 },
  ];

  const workbook = XLSX.utils.book_new();

  XLSX.utils.book_append_sheet(workbook, worksheet, "Alerts");

  XLSX.writeFile(
    workbook,
    `${fileName}_${new Date().toISOString().slice(0, 10)}.xlsx`
  );
};

/* =====================================================
        FLIGHT EXCEL
===================================================== */

export const downloadFlightExcel = (
  flights: FlightHistory[],
  fileName = "Flight_Report"
) => {
  const rows = flights.map((flight, index) => ({
    "Sr No": index + 1,
    "Drone ID": flight.drone?.droneId ?? "-",
    Drone: flight.drone?.droneOSName ?? "-",
    Sensor: flight.sensorId,
    Dispatched: formatDate(flight.dispatchedAt),
  }));

  const worksheet = XLSX.utils.json_to_sheet(rows);

  worksheet["!cols"] = [
    { wch: 8 },
    { wch: 18 },
    { wch: 25 },
    { wch: 18 },
    { wch: 22 },
  ];

  const workbook = XLSX.utils.book_new();

  XLSX.utils.book_append_sheet(workbook, worksheet, "Flights");

  XLSX.writeFile(
    workbook,
    `${fileName}_${new Date().toISOString().slice(0, 10)}.xlsx`
  );
};