import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

import type { Alert } from "@/lib/api/alerts";
import type { FlightHistory } from "@/lib/api/flightHistory";

const formatDate = (date: string) =>
  new Date(date).toLocaleString("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  });

function drawHeader(doc: jsPDF, title: string) {
  doc.setFont("helvetica", "bold");
  doc.setFontSize(20);

  doc.setTextColor(139, 0, 0);
  doc.text("ICCS COMMAND CENTER", 14, 18);

  doc.setFontSize(14);
  doc.setTextColor(30);

  doc.text(title, 14, 28);

  doc.setFontSize(10);

  doc.text(
    `Generated : ${new Date().toLocaleString()}`,
    14,
    36
  );

  doc.line(14, 42, 196, 42);
}

function drawFooter(doc: jsPDF) {
  const pages = doc.getNumberOfPages();

  for (let i = 1; i <= pages; i++) {
    doc.setPage(i);

    doc.setFontSize(9);

    doc.text(
      `Page ${i} of ${pages}`,
      170,
      290
    );

    doc.text(
      "ICCS Monitoring System",
      14,
      290
    );
  }
}
export const generateAlertPDF = (
  alerts: Alert[],
  stats: {
    total: number;
    active: number;
    sent: number;
    neutralised: number;
  }
) => {
  const doc = new jsPDF({
  orientation: "landscape",
  unit: "mm",
  format: "a3",
});

  drawHeader(doc, "Alert History Report");

  doc.setFontSize(11);

  doc.text(`Total Alerts : ${stats.total}`, 14, 52);

  doc.text(`Active : ${stats.active}`, 70, 52);

  doc.text(`Drone Sent : ${stats.sent}`, 120, 52);

  doc.text(`Neutralised : ${stats.neutralised}`, 180, 52);

  autoTable(doc, {
    startY: 60,
head: [[
  "Alert ID",
  "Type",
  "Sensor",
  "Area",

  "Latitude",
  "Longitude",

  "Message",
  "Status",
  "Created"
]],

body: alerts.map(alert => [
  alert.id,
  alert.type,
  alert.sensor?.name ?? "-",
  alert.sensor?.area?.name ?? "-",

  alert.sensor?.latitude ?? "-",
  alert.sensor?.longitude ?? "-",

  alert.message,
  alert.status,
  formatDate(alert.createdAt),
]),

    styles: {
      fontSize: 8,
      cellPadding: 3,
      valign: "middle",
    },

    headStyles: {
      fillColor: [139, 0, 0],
      textColor: [255, 255, 255],
      fontStyle: "bold",
    },

    alternateRowStyles: {
      fillColor: [245, 245, 245],
    },
  });

  drawFooter(doc);

  doc.save(
    `Alert_Report_${new Date().toISOString().slice(0, 10)}.pdf`
  );
};

/* =====================================================
                FLIGHT PDF
===================================================== */

export const generateFlightPDF = (
  flights: FlightHistory[],
  stats: {
    total: number;
    dispatched: number;
  }
) => {
  const doc = new jsPDF("landscape");

  drawHeader(doc, "Drone Flight History Report");

  doc.setFontSize(11);

  doc.text(`Total Flights : ${stats.total}`, 14, 52);

  doc.text(`Dispatched : ${stats.dispatched}`, 90, 52);

  autoTable(doc, {
    startY: 60,

    head: [[
      "Drone ID",
      "Drone Name",
      "Sensor",
      "Dispatched At",
    ]],

    body: flights.map((flight) => [
      flight.drone?.droneId ?? "-",
      flight.drone?.droneOSName ?? "-",
      flight.sensorId,
      formatDate(flight.dispatchedAt),
    ]),

    styles: {
      fontSize: 9,
      cellPadding: 4,
      valign: "middle",
    },

    headStyles: {
      fillColor: [139, 0, 0],
      textColor: [255, 255, 255],
      fontStyle: "bold",
    },

    alternateRowStyles: {
      fillColor: [245, 245, 245],
    },
  });

  drawFooter(doc);

  doc.save(
    `Flight_Report_${new Date().toISOString().slice(0, 10)}.pdf`
  );
};